from __future__ import annotations

# Curated leakage-safe few-shot examples for the '퓨샷만'/'동적퓨샷' ③+④ combos — every
# example below comes from a document OUTSIDE the scored benchmark (DOC-000, DOC-021..040,
# or the exception sheet's own synthetic DOC-000-<initials>-<n> snippets), so using them in
# a review prompt never leaks the answer for a document that later gets scored. Sourced
# from data/qa_dataset/qa_dataset_frozen.xlsx's 'golden dataset' and '예외조건 golden
# dataset' sheets (see docs/experiments/ for the selection plan). No synthetic content —
# a rule with nothing safe to show here just has an empty/missing entry.
#
# Priority rules (per the Phase 1/2 error-pattern analysis, docs/progress.md 2026-08-10):
# AE-03 (판단 근거 없이 '애매하면 다 AE-03'으로 오용됨), MI-02, TC-02, AE-04 — these got the
# most deliberate selection; the rest were picked by taking the first 1-2 leakage-safe
# candidates per rule.


class FewShotExample:
    __slots__ = ("original_text", "rationale")

    def __init__(self, original_text: str, rationale: str) -> None:
        self.original_text = original_text
        self.rationale = rationale


class FewShotException:
    __slots__ = ("original_text", "exception_condition", "rationale")

    def __init__(self, original_text: str, exception_condition: str, rationale: str) -> None:
        self.original_text = original_text
        self.exception_condition = exception_condition
        self.rationale = rationale


